"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2464],{36091:e=>{e.exports=JSON.parse('{"functions":[{"name":"SetFuel","desc":"Record an authoritative fuel snapshot. `serverTime` must be the server\'s own\\n`workspace:GetServerTimeNow()` reading as carried by `TrainStateSync` \u2014 never\\na locally read clock, which is what produced the 0% bug.","params":[{"name":"fuel","desc":"","lua_type":"number"},{"name":"rate","desc":"","lua_type":"number"},{"name":"isBraked","desc":"","lua_type":"boolean"},{"name":"isStalled","desc":"","lua_type":"boolean"},{"name":"serverTime","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":55,"path":"src/ReplicatedStorage/SharedModules/TrainStateCache.luau"}},{"name":"GetFuel","desc":"The last fuel snapshot, or `nil` if the server has not sent one yet.","params":[],"returns":[{"desc":"","lua_type":"FuelSnapshot?\\n"}],"function_type":"static","source":{"line":69,"path":"src/ReplicatedStorage/SharedModules/TrainStateCache.luau"}},{"name":"PredictedFuel","desc":"Fuel extrapolated from the last snapshot to now, clamped to\\n`[0, TrainConfig.MAX_FUEL]`. Returns `nil` if no snapshot has arrived.","params":[],"returns":[{"desc":"","lua_type":"number?\\n"}],"function_type":"static","source":{"line":78,"path":"src/ReplicatedStorage/SharedModules/TrainStateCache.luau"}},{"name":"SetShield","desc":"Record an authoritative shield snapshot.","params":[{"name":"current","desc":"","lua_type":"number"},{"name":"max","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":91,"path":"src/ReplicatedStorage/SharedModules/TrainStateCache.luau"}},{"name":"ShieldFraction","desc":"Shield as a 0..1 fraction of its max, or `nil` if no snapshot has arrived.","params":[],"returns":[{"desc":"","lua_type":"number?\\n"}],"function_type":"static","source":{"line":99,"path":"src/ReplicatedStorage/SharedModules/TrainStateCache.luau"}}],"properties":[],"types":[],"name":"TrainStateCache","desc":"Last-known authoritative train fuel and shield snapshots, plus the fuel\\nextrapolation every readout shares.\\n\\nThis exists because a snapshot reaches the client through two hops that can\\nboth be missed: the network packet (dispatched into a backlog-free signal at\\n`Packet` require time) and the in-process `Signals` re-publish. A controller\\nthat connects after either fire would otherwise have nothing \u2014 and the bug\\nthis module fixes was controllers filling that gap with invented snapshots\\nseeded from `workspace:GetServerTimeNow()` read at module load, before the\\nclient\'s clock estimate had converged, which extrapolated straight to 0%.\\n\\nEvery getter returns `nil` until the server has actually sent a snapshot.\\nThat is the point: there is no default, so nothing downstream can invent one.\\nCallers render a placeholder while the answer is `nil`.\\n\\nWritten by the bridge scripts (`TrainClient`, `TrainShieldController`)\\nimmediately *before* they fire the corresponding `Signals` event, so the\\ncache is never behind the signal.","realm":["Client"],"source":{"line":27,"path":"src/ReplicatedStorage/SharedModules/TrainStateCache.luau"}}')}}]);